            align-items: center;
            justify-content: center;
            width: clamp(1.2rem, 2vw, 1.6rem);
            height: clamp(1.2rem, 2vw, 1.6rem);
            font-family: var(--font-mono);
            font-size: var(--label-size);
            font-weight: 700;
            border-radius: 3px;
        }

        .rank-top { background: var(--accent-red); color: #fff; }
        .rank-reg { background: var(--bg-card-alt); color: var(--text-secondary); }

        .lang-name {
            font-family: var(--font-body);
            font-weight: 600;
            font-size: var(--small-size);
        }

        .prev-rank {
            font-family: var(--font-mono);
            font-size: var(--label-size);
            color: var(--text-muted);
            text-align: center;
        }

        .pct-cell {
            text-align: right;
            font-family: var(--font-mono);
            font-size: var(--small-size);
            font-weight: 700;
            white-space: nowrap;
        }

        .pct-bar-cell { width: clamp(4rem, 10vw, 12rem); }

        .pct-bar-wrap {
            display: flex;
            align-items: center;
            gap: 0.4rem;
        }

        .pct-bar-bg {
            flex: 1;
            height: 4px;
            background: var(--bg-card-alt);
            border-radius: 2px;
            overflow: hidden;
        }

        .pct-bar-fill {
            height: 100%;
            border-radius: 2px;
            background: var(--accent-red);
            transition: width 1s var(--ease-out-expo) 0.3s;
            width: 0%;
        }

        .slide.visible .pct-bar-fill {
            /* width is set by inline style; transition kicks in */
        }

        .chg-cell {
            text-align: right;
            font-family: var(--font-mono);
            font-size: var(--small-size);
            font-weight: 700;
            white-space: nowrap;
        }

        .chg-pos { color: var(--accent-green); }
        .chg-neg { color: var(--accent-red); }
        .chg-neu { color: var(--text-muted); }

        .rank-arrow {
            font-size: var(--label-size);
            display: inline-block;
        }

        .arrow-up   { color: var(--accent-green); }
        .arrow-down { color: var(--accent-red); }
        .arrow-flat { color: var(--text-muted); }

        /* ===========================================
           SLIDE 3 — BIGGEST MOVERS
           =========================================== */
        #slide-movers {
            background: var(--bg-primary);
        }

        #slide-movers .layout {
            display: grid;
            grid-template-rows: auto 1fr;
            height: 100%;
            padding: var(--slide-padding);
            gap: clamp(0.5rem, 1.5vh, 1.5rem);
        }

        .movers-split {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1rem, 3vw, 3rem);
            overflow: hidden;
        }

        .movers-panel {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1vh, 1rem);
            overflow: hidden;
        }

        .panel-label {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            font-family: var(--font-mono);
            font-size: var(--label-size);
            letter-spacing: 0.1em;
            text-transform: uppercase;
            margin-bottom: clamp(0.2rem, 0.5vh, 0.5rem);
        }

        .mover-card {
            background: var(--bg-card);
            border-radius: 4px;
            padding: clamp(0.5rem, 1.2vh, 1rem) clamp(0.75rem, 1.5vw, 1.25rem);
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1.5vw, 1rem);
            border: 1px solid var(--border-subtle);
            position: relative;
            overflow: hidden;
        }

        .mover-card.gainer { border-left: 3px solid var(--accent-green); }
        .mover-card.loser  { border-left: 3px solid var(--accent-red); }

        .mover-delta {
            font-family: var(--font-display);
            font-size: clamp(1rem, 2.5vw, 1.75rem);
            line-height: 1;
            min-width: 3ch;
            text-align: right;
        }

        .mover-delta.pos { color: var(--accent-green); }
        .mover-delta.neg { color: var(--accent-red); }

        .mover-info {
            flex: 1;
        }

        .mover-name {
            font-family: var(--font-body);
            font-weight: 700;
            font-size: var(--body-size);
            color: var(--text-primary);
        }

        .mover-ranks {
            font-family: var(--font-mono);
            font-size: var(--label-size);
            color: var(--text-secondary);
            margin-top: 0.2em;
        }

        .mover-pct {
            font-family: var(--font-mono);
            font-size: var(--label-size);
            font-weight: 700;
        }
        .mover-pct.pos { color: var(--accent-green); }
        .mover-pct.neg { color: var(--accent-red); }

        .divider-line {
            position: absolute;
            left: 50%;
            top: var(--slide-padding);
            bottom: var(--slide-padding);
            width: 1px;
            background: var(--border-mid);
            transform: translateX(-50%);
        }

        /* ===========================================
           SLIDE 4 — HISTORICAL
           =========================================== */
        #slide-historical {
            background: var(--bg-primary);
        }

        #slide-historical .layout {
            display: grid;
            grid-template-rows: auto 1fr;
            height: 100%;
            padding: var(--slide-padding);
            gap: clamp(0.5rem, 1.5vh, 1.5rem);
        }

        .historical-body {
            display: grid;
            grid-template-columns: 1.1fr 0.9fr;
            gap: clamp(1rem, 3vw, 3rem);
            overflow: hidden;
            min-height: 0;
        }

        .hist-table-wrap {
            overflow: hidden;
            display: flex;
            flex-direction: column;
            min-height: 0;
        }

        .hist-table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--label-size);
        }

        .hist-table th {
            font-family: var(--font-mono);
            font-size: calc(var(--label-size) * 0.9);
            color: var(--text-muted);
            padding: clamp(0.2rem, 0.5vh, 0.4rem) clamp(0.3rem, 0.8vw, 0.6rem);
            border-bottom: 1px solid var(--border-mid);
            text-align: center;
            letter-spacing: 0.05em;
            text-transform: uppercase;
        }

        .hist-table th.lang-col { text-align: left; }

        .hist-table td {
            padding: clamp(0.2rem, 0.5vh, 0.4rem) clamp(0.3rem, 0.8vw, 0.6rem);
            text-align: center;
            border-bottom: 1px solid var(--border-subtle);
            font-family: var(--font-mono);
            color: var(--text-secondary);
            font-size: calc(var(--label-size) * 0.9);
        }

        .hist-table td.lang-name-col {
            text-align: left;
            font-family: var(--font-body);
            font-weight: 600;
            font-size: var(--label-size);
            color: var(--text-primary);
        }

        .hist-table td.rank-1 { color: var(--accent-red); font-weight: 700; }
        .hist-table td.rank-2 { color: #ff8866; font-weight: 700; }
        .hist-table td.rank-3 { color: var(--accent-yellow); font-weight: 600; }
        .hist-table td.rank-na { color: var(--text-muted); }

        .hist-trend-panel {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
            overflow: hidden;
            min-height: 0;
        }

        .trend-item {
            background: var(--bg-card);
            border-radius: 4px;
            padding: clamp(0.5rem, 1.2vh, 1rem) clamp(0.75rem, 1.5vw, 1.25rem);
            border: 1px solid var(--border-subtle);
            position: relative;
            overflow: hidden;
        }

        .trend-item::before {
            content: '';
            position: absolute;
            left: 0;
            top: 0;
            bottom: 0;
            width: 3px;
        }

        .trend-item.t-python::before { background: var(--accent-yellow); }
        .trend-item.t-c::before      { background: var(--accent-blue); }
        .trend-item.t-java::before   { background: #ff8800; }
        .trend-item.t-js::before     { background: #f0db4f; }

        .trend-lang {
            font-family: var(--font-body);
            font-weight: 700;
            font-size: var(--body-size);
            color: var(--text-primary);
            margin-bottom: 0.2em;
        }

        .trend-desc {
            font-size: var(--label-size);
            color: var(--text-secondary);
            line-height: 1.45;
        }

        /* ===========================================
           SLIDE 5 — HALL OF FAME
           =========================================== */
        #slide-hof {
            background: var(--bg-primary);
        }

        #slide-hof .layout {
            display: grid;
            grid-template-rows: auto 1fr;
            height: 100%;
            padding: var(--slide-padding);
            gap: clamp(0.5rem, 1.5vh, 1.5rem);
        }

        .hof-body {
            display: grid;
            grid-template-columns: auto 1fr;
            gap: clamp(1rem, 3vw, 3rem);
            overflow: hidden;
            align-items: start;
        }

        .hof-winners-col {
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.8vh, 0.7rem);
            overflow: hidden;
        }

        .hof-row {
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1.5vw, 1rem);
            padding: clamp(0.3rem, 0.8vh, 0.6rem) clamp(0.6rem, 1.2vw, 1rem);
            background: var(--bg-card);
            border-radius: 4px;
            border: 1px solid var(--border-subtle);
        }

        .hof-row.python-winner {
            border-color: rgba(255,204,0,0.3);
            background: rgba(255,204,0,0.06);
        }

        .hof-row.csharp-winner {
            border-color: rgba(0,136,255,0.25);
            background: rgba(0,136,255,0.05);
        }

        .hof-year {
            font-family: var(--font-mono);
            font-size: var(--label-size);
            font-weight: 700;
            color: var(--text-muted);
            min-width: 3ch;
        }

        .hof-lang {
            font-family: var(--font-body);
            font-weight: 700;
            font-size: var(--body-size);
            color: var(--text-primary);
            flex: 1;
        }

        .hof-badge {
            font-family: var(--font-mono);
            font-size: var(--label-size);
            font-weight: 700;
            padding: 0.15em 0.5em;
            border-radius: 2px;
        }

        .badge-python  { background: rgba(255,204,0,0.2); color: var(--accent-yellow); }
        .badge-csharp  { background: rgba(0,136,255,0.2); color: var(--accent-blue); }

        .hof-insights {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
            overflow: hidden;
        }

        .insight-card {
            background: var(--bg-card);
            border-radius: 4px;
            padding: clamp(0.6rem, 1.5vh, 1.2rem) clamp(0.75rem, 1.5vw, 1.25rem);
            border: 1px solid var(--border-subtle);
        }

        .insight-card .ic-title {
            font-family: var(--font-body);
            font-weight: 700;
            font-size: var(--body-size);
            color: var(--text-primary);
            margin-bottom: 0.3em;
        }

        .insight-card .ic-body {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .big-stat {
            font-family: var(--font-display);
            font-size: clamp(2rem, 6vw, 4.5rem);
            color: var(--accent-yellow);
            line-height: 1;
        }

        .big-stat-label {
            font-family: var(--font-mono);
            font-size: var(--label-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-top: 0.3em;
        }

        /* ===========================================
           SLIDE 6 — TAKEAWAYS
           =========================================== */
        #slide-takeaways {
            background: var(--bg-primary);
        }

        #slide-takeaways .layout {
            display: grid;
            grid-template-rows: auto 1fr;
            height: 100%;
            padding: var(--slide-padding);
            gap: clamp(0.5rem, 1.5vh, 1.5rem);
        }

        .takeaways-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            grid-template-rows: 1fr 1fr;
            gap: clamp(0.5rem, 1.5vw, 1.25rem);
            overflow: hidden;
            min-height: 0;
        }

        .tk-card {
            background: var(--bg-card);
            border-radius: 4px;
            padding: clamp(0.75rem, 1.8vh, 1.5rem) clamp(0.75rem, 1.5vw, 1.5rem);
            border: 1px solid var(--border-subtle);
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.8vh, 0.6rem);
            overflow: hidden;
            position: relative;
        }

        .tk-card .tk-num {
            font-family: var(--font-mono);
            font-size: var(--label-size);
            color: var(--text-muted);
            letter-spacing: 0.1em;
        }

        .tk-card .tk-title {
            font-family: var(--font-body);
            font-weight: 700;
            font-size: var(--body-size);
            color: var(--text-primary);
            line-height: 1.3;
        }

        .tk-card .tk-body {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .tk-card .tk-stat {
            font-family: var(--font-display);
            font-size: clamp(1.25rem, 3vw, 2.25rem);
            line-height: 1;
            margin-bottom: 0.1em;
        }

        .tk-card.card-python { border-top: 3px solid var(--accent-yellow); }
        .tk-card.card-c      { border-top: 3px solid var(--accent-blue); }
        .tk-card.card-legacy { border-top: 3px solid var(--accent-green); }
        .tk-card.card-go     { border-top: 3px solid var(--accent-red); }

        .conclusion-bar {
            background: var(--accent-red);
            border-radius: 3px;
            padding: clamp(0.5rem, 1.2vh, 1rem) clamp(1rem, 2.5vw, 2rem);
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 1rem;
            flex-wrap: wrap;
        }

        .conclusion-bar .cb-text {
            font-family: var(--font-body);
            font-weight: 700;
            font-size: var(--body-size);
            color: #fff;
        }

        .conclusion-bar .cb-meta {
            font-family: var(--font-mono);
            font-size: var(--label-size);
            color: rgba(255,255,255,0.7);
            text-transform: uppercase;
            letter-spacing: 0.08em;
        }
    </style>
</head>
